type Manifest={patchId:string;patchFile:string;createdAt:string;projectRoot:string;files:Array<{path:string;existed:boolean;beforeSha256:string;eol:'LF'|'CRLF';bom:boolean}>;createdFiles:string[];generatedDirs:Array<{path:string;existed:boolean}>};

